    const tx=[...state.income.map(i=>{const x=incomeCalc(i);return{date:i.date||`${i.month}-01`,type:"Income",title:`Property income — ${readableMonth(i.month)}`,amount:x.netOwner,cls:"vc-positive"};}),...state.expenses.map(e=>({date:e.date,type:"Expense",title:e.description||e.category,amount:-Number(e.amount||0),cls:"vc-negative"})),...state.billing.map(e=>({date:`${e.month}-01`,type:"Billing",title:e.description||e.category,amount:e.paidBy==="Owner"?-Number(e.amount||0):0,cls:e.paidBy==="Owner"?"vc-negative":"text-muted"}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);
