  function updateIncomeCalculation(){const gross=Number(document.getElementById("income-gross")?.value)||0,mp=Number(document.getElementById("income-manager")?.value??state.settings.managerPercent)||0,tdsPct=Number(document.getElementById("income-tds")?.value??state.settings.tdsPercent)||0,gstPct=Number(state.settings.gstPercent)||0,manager=gross*mp/100,owner=Math.max(0,gross-manager),gst=gross*gstPct/100,tds=owner*tdsPct/100,total=gross+gst,net=owner-tds,set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=money(v)};set("calc-gross",gross);set("calc-manager",manager);set("calc-owner",owner);set("calc-gst",gst);set("calc-tds",tds);set("calc-total",total);set("calc-net",net);const setp=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=`(${v}%)`};setp("calc-manager-pct",mp);setp("calc-owner-pct",Math.max(0,100-mp));setp("calc-gst-pct",gstPct);setp("calc-tds-pct",tdsPct);const oa=document.getElementById("income-owner-auto");if(oa)oa.textContent=`${Math.max(0,100-mp)}%`;}
