  function buildReportText(report,month){const title=reportTitle(report), rows=reportRows(report,month);if(report==="financial"){const income=state.income.filter(x=>!month||x.month===month),t=income.reduce((a,i)=>{const x=incomeCalc(i);a.gross+=x.gross;a.net+=x.netOwner;a.tds+=x.tds;return a},{gross:0,net:0,tds:0});const exp=state.expenses.filter(x=>!month||String(x.date).startsWith(month)).reduce((s,x)=>s+Number(x.amount||0),0);return `${title} — Villa Caetano\n${month?readableMonth(month):"All months"}\n\nProperty income: ${money(t.gross)}\nTDS paid: ${money(t.tds)}\nNet owner revenue: ${money(t.net)}\nOne-off expenses: ${money(exp)}\nNet cashflow: ${money(t.net-exp)}`;}return `${title} — Villa Caetano\n${month?readableMonth(month):"All months"}\n\nRecords: ${rows.length}\n\n${rows.slice(0,30).map((x,i)=>`${i+1}. ${x.title||x.description||x.category} — ${x.amount!==undefined?money(Math.abs(x.amount)):""}`).join("\n")}`;}
